import sys
def solve(raw):
 ds=[]
 for x in raw.strip().split(";"):
  if x.strip(): ds.append(int(x.rsplit(",",1)[1].strip()))
 ds.sort()
 return ", ".join(str(ds[0] if i==0 else ds[i]-ds[i-1]) for i in range(len(ds)))
if __name__=="__main__": print(solve(sys.stdin.read()))

import sys
def solve(n):
 seen=set()
 while n!=1 and n not in seen:
  seen.add(n); s=0
  while n: n,d=divmod(n,10); s+=d*d
  n=s
 return "1" if n==1 else "0"
if __name__=="__main__": print(solve(int(sys.stdin.read())))
